insert into public.pendencias (cliente_id,titulo,detalhe,prioridade,quem)
select c.id,v.t,v.d,v.p,v.q
from (values
(null::text,$q$Nenhuma postagem em 30 dias$q$,$q$Os 15 perfis estão sem postagem no último mês. Posso publicar uma por perfil, com um serviço real e a cidade, sem preço, oferta ou prazo. Aguardo o seu OK para começar.$q$,$q$media$q$,$q$eu$q$),
(null::text,$q$Aba Produtos fora do alcance$q$,$q$O Windsor não lê nem cria produtos. Vale mais para Eletro Company, Garagem 3, as óticas e a Bilumix. Só dá para fazer pelo Chrome.$q$,$q$media$q$,$q$bloq$q$),
(null::text,$q$Demais empresas não aparecem no Windsor$q$,$q$Você citou cerca de 20 empresas e aqui aparecem 15. O Drive tem pastas de outros clientes (Cleide, Moraes Eletrônicos, ACDelco, Fire Moda Fitness, Usina Agro Ambiental, ROInfluencer, Franciele Bill, Fernanda Luiza). Falta conectar os perfis delas.$q$,$q$alta$q$,$q$voce$q$),
($q$otica-av-rio-de-janeiro$q$,$q$3 avaliações de 1 estrela sem resposta$q$,$q$Keti Xavier, Jakeline Torres e Dorvalina Ferreira Xavier (6 e 7/11). Estão retidas até você decidir se responde ou pede revisão ao Google.$q$,$q$alta$q$,$q$voce$q$),
($q$otica-av-rio-de-janeiro$q$,$q$Capa vertical$q$,$q$A capa tem 2000×3556, em pé. Preciso de uma foto horizontal da fachada. A Saul Elkind está igual.$q$,$q$alta$q$,$q$voce$q$),
($q$otica-av-rio-de-janeiro$q$,$q$Serviços sem descrição$q$,$q$19 serviços padrão do Google, nenhum com texto. Vou acrescentar serviços com descrição curta e a cidade.$q$,$q$media$q$,$q$eu$q$),
($q$otica-av-rio-de-janeiro$q$,$q$Poucas fotos novas$q$,$q$Só 2 no último mês. Confiro a pasta da unidade no Drive e subo o que faltar.$q$,$q$media$q$,$q$eu$q$),
($q$otica-av-rio-de-janeiro$q$,$q$Nome com palavras-chave e cidade$q$,$q$O nome do perfil é "Ótica Gouveia | Óculos de Grau,Lentes - Av. Rio de Janeiro em Londrina". O Google pede só o nome real do negócio, e nomes com serviço e cidade podem levar à suspensão. Trocar exige o Chrome e a sua aprovação.$q$,$q$baixa$q$,$q$bloq$q$),
($q$otica-joao-candido$q$,$q$Área de atendimento vazia$q$,$q$As unidades Rio de Janeiro e Souza Naves listam Londrina, Cambé, Ibiporã e Rolândia. Aplico a mesma lista.$q$,$q$media$q$,$q$eu$q$),
($q$otica-joao-candido$q$,$q$Sem categorias adicionais$q$,$q$Adiciono "Loja de óculos de sol" e "Fornecedor de lentes de contato", que a descrição do perfil já confirma.$q$,$q$media$q$,$q$eu$q$),
($q$otica-joao-candido$q$,$q$Nome com palavras-chave e cidade$q$,$q$O nome do perfil é "Óticas Gouveia – Óculos e Lentes Londrina -Joao Cândido". O Google pede só o nome real do negócio, e nomes com serviço e cidade podem levar à suspensão. Trocar exige o Chrome e a sua aprovação.$q$,$q$baixa$q$,$q$bloq$q$),
($q$otica-sergipe$q$,$q$Sem fotos e sem capa$q$,$q$Nenhuma foto no último mês, sem capa e sem pasta no Drive. Envie fotos da loja, com uma horizontal da fachada.$q$,$q$alta$q$,$q$voce$q$),
($q$otica-sergipe$q$,$q$Sem categorias adicionais$q$,$q$Adiciono "Loja de óculos de sol" e "Fornecedor de lentes de contato", que a descrição do perfil já confirma.$q$,$q$media$q$,$q$eu$q$),
($q$otica-sergipe$q$,$q$Atributos quase vazios$q$,$q$Só o link do WhatsApp. Confirme pagamento, estacionamento e acessibilidade da unidade.$q$,$q$media$q$,$q$voce$q$),
($q$otica-sergipe$q$,$q$Descrição com dados da rede$q$,$q$O texto cita "desde 1979", que vale para a rede. Confirme se pode valer para a unidade Sergipe.$q$,$q$media$q$,$q$voce$q$),
($q$otica-souza-naves$q$,$q$Sem categorias adicionais$q$,$q$Adiciono "Loja de óculos de sol" e "Fornecedor de lentes de contato". "Relojoaria" e "Loja de acessórios" só depois do seu OK abaixo.$q$,$q$media$q$,$q$eu$q$),
($q$otica-souza-naves$q$,$q$Confirmar joias, relógios e presentes$q$,$q$Nome e descrição citam esses itens. Confirme que a unidade vende antes de eu criar serviços e categoria de relojoaria.$q$,$q$media$q$,$q$voce$q$),
($q$otica-souza-naves$q$,$q$Poucas fotos novas$q$,$q$Só 2 no último mês. Confiro a pasta da unidade no Drive e subo o que faltar.$q$,$q$media$q$,$q$eu$q$),
($q$otica-souza-naves$q$,$q$Nome com palavras-chave e cidade$q$,$q$O nome do perfil é "Óticas Gouveia - Óculos, Jóias, Relógios, Lentes de Contato e Presentes". O Google pede só o nome real do negócio, e nomes com serviço e cidade podem levar à suspensão. Trocar exige o Chrome e a sua aprovação.$q$,$q$baixa$q$,$q$bloq$q$),
($q$otica-saul-elkind$q$,$q$Capa vertical$q$,$q$A capa tem 2000×3556, em pé. Preciso de uma foto horizontal da fachada.$q$,$q$alta$q$,$q$voce$q$),
($q$otica-saul-elkind$q$,$q$Poucas fotos novas$q$,$q$Só 3 no último mês. Confiro a pasta da unidade no Drive e subo o que faltar.$q$,$q$media$q$,$q$eu$q$),
($q$clinica-central-norte$q$,$q$Endereço em conflito$q$,$q$O perfil mostra Av. Saul Elkind, 1433. A descrição antiga citava Rua Lago Vitória, 696. Publiquei o texto sem endereço até você confirmar qual vale.$q$,$q$alta$q$,$q$voce$q$),
($q$clinica-central-norte$q$,$q$Resposta pronta e não publicada$q$,$q$A resposta para Yoru Sayuri ficou sem publicar porque a ação foi bloqueada. Com o seu OK eu publico.$q$,$q$alta$q$,$q$voce$q$),
($q$clinica-central-norte$q$,$q$Serviços sem descrição$q$,$q$34 serviços, nenhum com texto. Escrevo uma descrição curta para cada, com o bairro.$q$,$q$media$q$,$q$eu$q$),
($q$clinica-central-norte$q$,$q$Sem categorias adicionais$q$,$q$Só "Clínica odontológica". Posso incluir categorias da odontologia, como ortodontia e implantes, com o seu OK.$q$,$q$media$q$,$q$voce$q$),
($q$clinica-central-norte$q$,$q$Perfil duplicado$q$,$q$Existe outro perfil da clínica, em outra conta do Google e sem serviços. Não mexo nele. Decida entre pedir a remoção ou assumir o acesso.$q$,$q$media$q$,$q$voce$q$),
($q$clinica-central-norte$q$,$q$799 avaliações, só o último mês visível$q$,$q$O teste do Windsor lê só 30 dias. Respostas atrasadas nas avaliações antigas só aparecem pelo Chrome ou com plano pago.$q$,$q$media$q$,$q$bloq$q$),
($q$clinica-central-norte$q$,$q$Confirmar a capa$q$,$q$Não vi capa nova no último mês, e o Windsor só lê esse período. Se o perfil já tem capa horizontal, está certo.$q$,$q$baixa$q$,$q$voce$q$),
($q$clinica-central-norte$q$,$q$Área de atendimento vazia$q$,$q$É opcional para consultório com endereço. Posso listar Londrina e Cambé.$q$,$q$baixa$q$,$q$eu$q$),
($q$dra-ana-luiza$q$,$q$Sem fotos e sem capa$q$,$q$Nenhuma foto vista no último mês e sem pasta no Drive. Envie fotos do consultório e da Dra.$q$,$q$alta$q$,$q$voce$q$),
($q$dra-ana-luiza$q$,$q$Atributos vazios$q$,$q$Nenhum atributo preenchido: pagamento, acessibilidade, agendamento online, WhatsApp. Confirme o que vale.$q$,$q$alta$q$,$q$voce$q$),
($q$dra-ana-luiza$q$,$q$17 avaliações não lidas$q$,$q$Todas têm mais de 30 dias e o Windsor Trial não mostra se foram respondidas. Só pelo Chrome ou com plano pago.$q$,$q$alta$q$,$q$bloq$q$),
($q$dra-ana-luiza$q$,$q$Sem categorias adicionais$q$,$q$Só "Dentista". A sugestão era dentista estético. Falta o seu OK para incluir.$q$,$q$media$q$,$q$voce$q$),
($q$dra-ana-luiza$q$,$q$Confirmar "lentes de contato dental"$q$,$q$O serviço está no perfil. Confirme que a Dra. faz.$q$,$q$media$q$,$q$voce$q$),
($q$dra-ana-luiza$q$,$q$Sem horário de sábado$q$,$q$Atende de segunda a sexta. Confirme se abre aos sábados.$q$,$q$baixa$q$,$q$voce$q$),
($q$eletro-company$q$,$q$Confirmar a capa$q$,$q$Não vi capa nova no último mês, e o Windsor só lê esse período. Se o perfil já tem capa horizontal, está certo.$q$,$q$baixa$q$,$q$voce$q$),
($q$garagem-3$q$,$q$2 avaliações retidas$q$,$q$Uma avaliação de 29/10 e a de Andrey Jr, anterior, estão sem resposta. Segurei as duas até você decidir como responder.$q$,$q$alta$q$,$q$voce$q$),
($q$garagem-3$q$,$q$Atributos vazios$q$,$q$Nenhum atributo: pagamento, estacionamento, acessibilidade, link de WhatsApp. Confirme o que existe na loja.$q$,$q$media$q$,$q$voce$q$),
